cssHead:
body {
  font-family: 'Geist', sans-serif;
  background-color: #f9faf7;
  color: #203e35;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}
.font-serif {
  font-family: 'EB Garamond', serif;
}
/* MIA 3D Sphere Logo */
.mia-sphere {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #5d8a77 0%, #305649 45%, #183129 85%, #0e1e19 100%);
  box-shadow: 0 4px 10px rgba(32, 62, 53, 0.22), inset 0 1px 2px rgba(255, 255, 255, 0.4);
  display: inline-block;
}
